steps.sampleSolution:
#include <iostream>
#include <memory>

struct Sensor {
    int id;
    double temp;
};

int main() {
    auto s = std::make_unique<Sensor>();
    s->id = 1;
    std::cout << "Sensor " << s->id << "\n";
    return 0;
}
